"""Calibrate a line-final permutation test while fixing selected endings."""

import json
from math import sqrt
from pathlib import Path
import random
from statistics import median
import sys

from vs import corpus


def upper_tail(lines):
    """Exact inclusive tail for independent terminal draws conditional on each line total."""
    observed = 0
    distribution = [1.0]
    for eligible, positives, final in lines:
        if positives in (0, eligible):
            assert final == (positives == eligible)
            continue
        observed += final
        probability = positives / eligible
        distribution.append(0.0)
        for k in range(len(distribution) - 1, 0, -1):
            distribution[k] = (
                distribution[k] * (1 - probability) + distribution[k - 1] * probability
            )
        distribution[0] *= 1 - probability
    return min(1.0, sum(distribution[observed:]))


def wilson(successes, trials):
    p = successes / trials
    z = 1.959963984540054
    scale = 1 + z * z / trials
    centre = (p + z * z / (2 * trials)) / scale
    radius = z * sqrt(p * (1 - p) / trials + z * z / (4 * trials * trials)) / scale
    return [max(0.0, centre - radius), min(1.0, centre + radius)]


def public_line_lengths(plan):
    public_training, _ = corpus.split_pages('practice', 'zl')
    lengths = [
        len(line.words)
        for page in public_training if page.language == 'B'
        for line in page.lines if line.unit == 'P' and len(line.words) >= 3
    ]
    return random.Random(plan['layout_seed']).choices(lengths, k=plan['lines_per_book'])


def run(plan):
    lengths = public_line_lengths(plan)
    order = list(range(len(lengths)))
    random.Random(plan['mask_seed']).shuffle(order)
    masks = {
        str(fraction): sorted(order[round(fraction * len(lengths)):])
        for fraction in plan['locked_fractions']
    }
    rng = random.Random(plan['simulation_seed'])
    trials = plan['books_per_rate']
    rows = {}
    for final_rate in plan['final_rates']:
        counts = dict.fromkeys(masks, 0)
        for _ in range(trials):
            lines = []
            for length in lengths:
                interior = sum(rng.random() < plan['interior_rate'] for _ in range(length - 2))
                final = rng.random() < final_rate
                lines.append((length - 1, interior + final, final))
            for locked, free_indices in masks.items():
                counts[locked] += upper_tail(lines[i] for i in free_indices) <= plan['alpha']
        rows[str(final_rate)] = {
            locked: {
                'rejections': count,
                'rate': count / trials,
                'wilson_95': wilson(count, trials),
            }
            for locked, count in counts.items()
        }
    assert all(row['1']['rejections'] == 0 for row in rows.values())
    return {
        'plan': plan,
        'layout': {'minimum': min(lengths), 'median': median(lengths), 'maximum': max(lengths)},
        'power': rows,
    }


def main():
    assert upper_tail([]) == 1.0
    assert abs(upper_tail([(5, 1, True)]) - .2) < 1e-12
    assert abs(upper_tail([(5, 1, True), (4, 1, True)]) - .05) < 1e-12
    assert upper_tail([(3, 3, True), (2, 0, False)]) == 1.0
    plan = json.loads(Path(sys.argv[1]).read_text())
    result = run(plan)
    Path(sys.argv[2]).write_text(json.dumps(result, indent=2) + '\n')
    for rate, fractions in result['power'].items():
        print(rate, {fraction: round(row['rate'], 3) for fraction, row in fractions.items()})


if __name__ == '__main__':
    main()
